use std::collections::BTreeMap;
struct LSMTree { memtable: BTreeMap<String, String>, sstables: Vec<BTreeMap<String, String>> }
impl LSMTree {
    fn new() -> Self { Self { memtable: BTreeMap::new(), sstables: Vec::new() } }
    fn put(&mut self, k: String, v: String) {
        self.memtable.insert(k, v);
        if self.memtable.len() >= 3 {
            self.sstables.push(self.memtable.clone());
            self.memtable.clear();
        }
    }
    fn get(&self, k: &str) -> Option<&String> {
        if let Some(v) = self.memtable.get(k) { return Some(v); }
        for sst in self.sstables.iter().rev() {
            if let Some(v) = sst.get(k) { return Some(v); }
        }
        None
    }
}

struct BTreeIndex { keys: Vec<String>, values: Vec<String> }
impl BTreeIndex {
    fn new() -> Self { Self { keys: Vec::new(), values: Vec::new() } }
    fn put(&mut self, k: String, v: String) { self.keys.push(k); self.values.push(v); }
    fn get(&self, k: &str) -> Option<&String> {
        let idx = self.keys.iter().position(|r| r == k)?;
        Some(&self.values[idx])
    }
}

