struct Coordinator2PC<P> { participants: Vec<P> }
impl<P: Participant> Coordinator2PC<P> {
    fn commit_tx(&self, tx_id: u64) -> &'static str {
        if self.participants.iter().all(|p| p.prepare(tx_id)) {
            for p in &self.participants { p.commit(tx_id); }
            return "Committed";
        }
        for p in &self.participants { p.abort(tx_id); }
        "Aborted"
    }
}
trait Participant { fn prepare(&self, tx: u64) -> bool; fn commit(&self, tx: u64); fn abort(&self, tx: u64); }

struct HashRouter { nodes: Vec<String> }
impl HashRouter {
    fn route(&self, key: &str) -> &String {
        let sum: u32 = key.bytes().map(|b| b as u32).sum();
        &self.nodes[(sum as usize) % self.nodes.len()]
    }
}

struct RangeRouter { boundaries: Vec<(String, String, String)> }
impl RangeRouter {
    fn route(&self, key: &str) -> &str {
        for (s, e, n) in &self.boundaries {
            if key >= s && key <= e { return n; }
        }
        "Node-Fallback"
    }
}

struct ProtobufEncoder;
impl ProtobufEncoder {
    fn encode_field(tag: u32, val_type: u32, val: &[u8]) -> Vec<u8> {
        let header = (tag << 3) | val_type;
        let mut buf = vec![header as u8];
        buf.extend_from_slice(val);
        buf
    }
}

struct AvroEncoder;
impl AvroEncoder {
    fn encode(fields: Vec<&[u8]>) -> Vec<u8> {
        fields.into_iter().flatten().copied().collect()
    }
}

use std::collections::HashMap;
struct SingleLeaderDB { leader: HashMap<String, String>, replicas: Vec<HashMap<String, String>> }
impl SingleLeaderDB {
    fn write(&mut self, k: String, v: String) {
        self.leader.insert(k.clone(), v.clone());
        for rep in &mut self.replicas { rep.insert(k.clone(), v.clone()); }
    }
    fn read(&self, k: &str) -> Option<&String> { self.replicas[0].get(k) }
}

struct LeaderlessQuorum { store: Vec<std::collections::HashMap<String, String>> }
impl LeaderlessQuorum {
    fn write(&mut self, k: String, v: String) {
        for node in &mut self.store { node.insert(k.clone(), v.clone()); }
    }
    fn read(&self, k: &str) -> Option<&String> { self.store[0].get(k) }
}

