struct ListHead { next: *mut ListHead, prev: *mut ListHead }
impl ListHead {
    unsafe fn add(new_node: *mut Self, head: *mut Self) {
        let next_node = (*head).next;
        (*new_node).next = next_node;
        (*new_node).prev = head;
        (*head).next = new_node;
        (*next_node).prev = new_node;
    }
}

struct LinuxKfifo<T> { buffer: Vec<Option<T>>, size: usize, incoming: usize, outgoing: usize }
impl<T> LinuxKfifo<T> {
    fn put(&mut self, val: T) -> bool {
        self.buffer[self.incoming & (self.size - 1)] = Some(val);
        self.incoming += 1; true
    }
    fn get(&mut self) -> Option<T> {
        let val = self.buffer[self.outgoing & (self.size - 1)].take();
        self.outgoing += 1; val
    }
}
